  "summary": "The code contains critical security vulnerabilities including SQL injection and OS command injection. Overall health is poor due to blocking I/O, lack of resource management, and hardcoded configurations. The fixed code implements parameterized queries, safe subprocess execution, and proper resource handling.",
  "fixed_code": "import sqlite3\nimport subprocess\nimport os\nimport re\nfrom flask import Flask, jsonify, request, Response\n\napp = Flask(__name__)\napp.config['DATABASE_PATH'] = os.getenv('DATABASE_PATH', 'reports.db')\n\n@app.route(\"/reports/<team>\")\ndef team_report(team: str) -> Response:\n    \"\"\"Fetch sales report for a specific team.\"\"\"\n    if not re.match(r'^[a-zA-Z0-9_]+$', team):\n        return jsonify(error=\"Invalid team name\"), 400\n    \n    with sqlite3.connect(app.config['DATABASE_PATH']) as conn:\n        rows = conn.execute('SELECT day, total FROM sales WHERE team = ? ORDER BY day', (team,)).fetchall()\n    return jsonify([list(r) for r in rows])\n\n@app.route(\"/reports/archive\", methods=[\"POST\"])\ndef archive_reports() -> Response:\n    \"\"\"Archive reports for a given name.\"\"\"\n    name = request.form.get(\"name\", \"\")\n    safe_name = os.path.basename(name)\n    if not safe_name or not re.match(r'^[a-zA-Z0-9_-]+$', safe_name):\n        return jsonify(error=\"Invalid archive name\"), 400\n\n    # Note: In production, offload this to a background task queue like Celery\n    subprocess.run(['tar', 'czf', f'/tmp/{safe_name}.tgz', 'reports/'], check=True)\n    return jsonify(archive=f\"/tmp/{safe_name}.tgz\")"
}
